/**
 * Line geometry for the code area. One logical line can wrap onto several
 * visual rows (`whitespace-pre-wrap`), so the gutter and the active-line band
 * read row counts from the rendered text instead of assuming one row per line.
 */

/** Height of one visual row, from the code area's computed line-height. */
export function rowHeight(code: HTMLElement): number {
  const style = getComputedStyle(code);
  const lineHeight = parseFloat(style.lineHeight);

  if (Number.isFinite(lineHeight) && lineHeight > 0) {
    return lineHeight;
  }

  // `normal` has no pixel value; 1.2 is the usual UA approximation.
  return parseFloat(style.fontSize) * 1.2 || 0;
}

interface TextRun {
  node: Text;
  start: number;
}

/** Every text node under `root` with its starting offset, from one walk. */
function textRuns(root: Node): TextRun[] {
  const walker = (root.ownerDocument ?? document).createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const runs: TextRun[] = [];
  const total = { offset: 0 };

  // eslint-disable-next-line no-restricted-syntax -- TreeWalker requires iteration with nextNode()
  for (let node = walker.nextNode(); node !== null; node = walker.nextNode()) {
    const text = node as Text;

    runs.push({ node: text, start: total.offset });
    total.offset += text.data.length;
  }

  return runs;
}

/** The run holding `target`, by binary search. A boundary offset resolves to the earlier run's end. */
function positionIn(runs: TextRun[], target: number): { node: Text; offset: number } | null {
  if (runs.length === 0) {
    return null;
  }

  const search = (low: number, high: number): number => {
    if (low >= high) {
      return low;
    }

    const mid = Math.ceil((low + high) / 2);

    return runs[mid].start < target ? search(mid, high) : search(low, mid - 1);
  };

  const run = runs[search(0, runs.length - 1)];

  return { node: run.node, offset: Math.min(target - run.start, run.node.data.length) };
}

/** Visual rows one non-empty line occupies, read from its text's client rects. */
function rowsOf(code: HTMLElement, runs: TextRun[], start: number, end: number, row: number): number {
  const from = positionIn(runs, start + 1);
  const to = positionIn(runs, end);

  if (!from || !to) {
    return 1;
  }

  const range = code.ownerDocument.createRange();

  range.setStart(from.node, Math.max(0, from.offset - 1));
  range.setEnd(to.node, to.offset);

  const rects = Array.from(range.getClientRects()).filter((rect) => rect.width > 0 || rect.height > 0);

  if (rects.length === 0) {
    return 1;
  }

  const top = Math.min(...rects.map((rect) => rect.top));
  const bottom = Math.max(...rects.map((rect) => rect.bottom));

  return Math.max(1, Math.round((bottom - top) / row));
}

/**
 * Visual rows per logical line. Skips per-line measuring when the text has no
 * wrapped line at all, which is the common case and keeps typing cheap.
 */
export function measureLineRows(code: HTMLElement): number[] {
  const text = code.textContent ?? '';
  const lines = text.split('\n');
  const row = rowHeight(code);
  const style = getComputedStyle(code);
  const contentHeight = code.clientHeight - parseFloat(style.paddingTop || '0') - parseFloat(style.paddingBottom || '0');

  if (row <= 0 || Math.round(contentHeight / row) <= lines.length) {
    return lines.map(() => 1);
  }

  const runs = textRuns(code);
  const starts = lines.reduce<number[]>((acc, _line, index) => {
    acc.push(index === 0 ? 0 : acc[index - 1] + lines[index - 1].length + 1);

    return acc;
  }, []);

  return lines.map((line, index) => (line === '' ? 1 : rowsOf(code, runs, starts[index], starts[index] + line.length, row)));
}

/** Logical line holding a collapsed caret inside `code`, or null when there is none. */
export function caretLineIndex(code: HTMLElement): number | null {
  const selection = code.ownerDocument.getSelection();

  if (!selection || selection.rangeCount === 0 || !selection.isCollapsed) {
    return null;
  }

  const caret = selection.getRangeAt(0);

  if (!code.contains(caret.startContainer)) {
    return null;
  }

  const before = code.ownerDocument.createRange();

  before.selectNodeContents(code);
  before.setEnd(caret.startContainer, caret.startOffset);

  return before.toString().split('\n').length - 1;
}

import { TAB_STRING } from './constants';

/**
 * Handle keydown events inside the code block.
 * Returns true if the event was handled (caller should preventDefault).
 */
export function handleCodeKeydown(
  event: KeyboardEvent,
  codeElement: HTMLElement,
  onExit: () => void
): boolean {
  if (event.key === 'Enter' && event.shiftKey) {
    onExit();
    return true;
  }

  if (event.key === 'Enter') {
    insertNewline(codeElement);
    return true;
  }

  if (event.key === 'Tab' && !event.shiftKey) {
    insertTab();
    return true;
  }

  if (event.key === 'Tab' && event.shiftKey) {
    removeTab(codeElement);
    return true;
  }

  return false;
}

/**
 * Map of opening brackets to their matching closers. Used by Enter handling to
 * decide whether the caret sits between a paired set of brackets, in which
 * case the closer is pushed to its own dedented line and the caret lands on
 * an indented middle line — same shape as VSCode/JetBrains defaults.
 */
const BRACKET_PAIRS: Record<string, string> = {
  '{': '}',
  '(': ')',
  '[': ']',
};

function insertNewline(codeElement: HTMLElement): void {
  const selection = window.getSelection();

  if (!selection || selection.rangeCount === 0) return;

  const range = selection.getRangeAt(0);

  const startOffset = computeCaretOffset(codeElement, range.startContainer, range.startOffset);
  const endOffset = computeCaretOffset(codeElement, range.endContainer, range.endOffset);

  const text = codeElement.textContent ?? '';
  const before = text.substring(0, startOffset);
  const after = text.substring(endOffset);

  // Leading whitespace of the line where the caret sits — auto-indent baseline.
  const lineStart = before.lastIndexOf('\n') + 1;
  const indentMatch = before.substring(lineStart).match(/^[ \t]*/);
  const indent = indentMatch ? indentMatch[0] : '';

  const charBefore = before.length > 0 ? before.charAt(before.length - 1) : '';
  const expectedCloser = BRACKET_PAIRS[charBefore];
  const charAfter = after.charAt(0);

  const { inserted, caretDelta } = computeNewlineInsertion({
    indent,
    afterOpener: expectedCloser !== undefined,
    betweenMatchedPair: expectedCloser !== undefined && charAfter === expectedCloser,
  });

  while (codeElement.firstChild) {
    codeElement.removeChild(codeElement.firstChild);
  }
  codeElement.appendChild(document.createTextNode(before + inserted + after));

  restoreCaretOffset(codeElement, startOffset + caretDelta);
}

function computeNewlineInsertion(opts: {
  indent: string;
  afterOpener: boolean;
  betweenMatchedPair: boolean;
}): { inserted: string; caretDelta: number } {
  const { indent, afterOpener, betweenMatchedPair } = opts;

  if (betweenMatchedPair) {
    return {
      inserted: `\n${indent}${TAB_STRING}\n${indent}`,
      caretDelta: 1 + indent.length + TAB_STRING.length,
    };
  }

  if (afterOpener) {
    return {
      inserted: `\n${indent}${TAB_STRING}`,
      caretDelta: 1 + indent.length + TAB_STRING.length,
    };
  }

  return {
    inserted: `\n${indent}`,
    caretDelta: 1 + indent.length,
  };
}

function computeCaretOffset(root: HTMLElement, container: Node, offset: number): number {
  const range = document.createRange();

  range.selectNodeContents(root);
  range.setEnd(container, offset);

  return range.toString().length;
}

function insertTab(): void {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return;

  const range = selection.getRangeAt(0);
  range.deleteContents();

  const tab = document.createTextNode(TAB_STRING);
  range.insertNode(tab);
  range.setStartAfter(tab);
  range.collapse(true);

  selection.removeAllRanges();
  selection.addRange(range);
}

/**
 * Count leading spaces on the line (up to TAB_STRING length).
 */
function countLeadingSpaces(lineContent: string): number {
  const limit = Math.min(TAB_STRING.length, lineContent.length);
  const match = lineContent.substring(0, limit).match(/^ */);

  return match ? match[0].length : 0;
}

function removeTab(codeElement: HTMLElement): void {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return;

  const range = selection.getRangeAt(0);
  const textContent = codeElement.textContent ?? '';

  const preCaretRange = range.cloneRange();
  preCaretRange.selectNodeContents(codeElement);
  preCaretRange.setEnd(range.startContainer, range.startOffset);

  const caretOffset = preCaretRange.toString().length;
  const lineStart = textContent.lastIndexOf('\n', caretOffset - 1) + 1;
  const lineContent = textContent.substring(lineStart);

