    "module": "esnext",
    "moduleResolution": "bundler", // This resolution strategy handles package.json exports and is suitable for modern bundlers
    "lib": ["dom", "es2017", "es2018", "es2019", "es2022"],
    "allowJs": true,

    // allows to import .json files for i18n
    "resolveJsonModule": true,

    // allows to omit export default in .json files
    "allowSyntheticDefaultImports": true,
    "experimentalDecorators": true,
    "jsx": "react-jsx",
    // No `baseUrl`: it is deprecated in TypeScript 6 (TS5101) and removed in 7.
    // Every mapping below is "./"-prefixed, so it resolves relative to this
    // file's directory without it.
    "paths": {
      "@/types": [ "./types/", "./docs/src/types" ],
      "@bloklabs/core": [ "./types/index.d.ts" ],
      "@bloklabs/core/markdown": [ "./types/markdown.d.ts" ],
