      "@/types/*": [ "./types/*", "./docs/src/types/*" ],
      "@/*": [ "./docs/src/*" ],
      "@editorjs/editorjs": [ "./types" ],
      "@editorjs/editorjs/*": [ "./types/*" ]
    },
    "esModuleInterop": true,
    "skipLibCheck": true,
    "allowArbitraryExtensions": true,
    "noEmit": true
  },
  "include": [
    "**/*.ts",
    "**/*.tsx",
    "**/*.js",
    "**/*.json",
    "vite.config*.mjs",
    ".storybook/**/*.ts"
